SEC-CORS-002.remediation:
Fix CORS configuration:

1. Never use wildcard (*) for sensitive APIs
2. Validate origin against whitelist
3. Avoid reflecting Origin header without validation
4. Only set credentials: true with specific trusted origins

For Express:
const whitelist = ['https://example.com', 'https://app.example.com'];
app.use(cors({
  origin: function (origin, callback) {
    if (whitelist.indexOf(origin) !== -1 || !origin) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true
}));

For Nginx:
if ($http_origin ~* (https://example\.com|https://app\.example\.com)) {
    add_header Access-Control-Allow-Origin $http_origin always;
    add_header Access-Control-Allow-Credentials true always;
}

SEC-API-001.remediation:
Require authentication for API endpoints:

For Express:
const authenticate = require('./middleware/auth');
app.use('/api', authenticate);

For REST APIs, use:
- API keys in headers
- OAuth 2.0 tokens
- JWT (JSON Web Tokens)

Example with JWT:
const jwt = require('jsonwebtoken');
app.use('/api', (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Unauthorized' });
  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    res.status(401).json({ error: 'Invalid token' });
  }
});

For Nginx:
location /api {
    auth_basic "API Access";
    auth_basic_user_file /etc/nginx/.htpasswd;
}

